mapper.update:
UPDATE room_members
SET last_seen_at = NOW()
WHERE room_id = #{roomId} AND user_id = #{userId}

mapper.select:
SELECT id, room_id, user_id, role, joined_at, last_seen_at
FROM room_members
WHERE room_id = #{roomId}
  AND user_id <> #{excludeUserId}
ORDER BY joined_at ASC, id ASC
LIMIT 1

